-- Exact rollback of CPF oracle initial baseline for cmnDB
BEGIN EXECUTE IMMEDIATE 'DROP TABLE cmn_sample_item CASCADE CONSTRAINTS PURGE'; EXCEPTION WHEN OTHERS THEN IF SQLCODE != -942 THEN RAISE; END IF; END;
/
